import{_ as a,o as s,c as i,a2 as t}from"./chunks/framework.BV2xZELn.js";const g=JSON.parse('{"title":"Versioning","description":"","frontmatter":{},"headers":[],"relativePath":"guide/versioning.md","filePath":"guide/versioning.md","lastUpdated":1791892741000}'),n={name:"guide/versioning.md"};function o(r,e,d,l,c,h){return s(),i("div",null,[...e[0]||(e[0]=[t(`<h1 id="versioning" tabindex="-1">Versioning <a class="header-anchor" href="#versioning" aria-label="Permalink to &quot;Versioning&quot;">​</a></h1><p>Sweetmelon core uses <a href="https://semver.org" target="_blank" rel="noreferrer">Semantic Versioning</a>. An app pins the core release it is built for in <code>sweetmelon.yaml</code>:</p><div class="language-yaml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">core</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;2.4&quot;</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br></div></div><table tabindex="0"><thead><tr><th>Release</th><th>Changes</th><th>What an app does</th></tr></thead><tbody><tr><td>Patch (<code>2.4.1</code>)</td><td>Bug fixes only. No change to behaviour, the JS bridge or <code>sweetmelon.yaml</code>.</td><td>Takes it safely.</td></tr><tr><td>Minor (<code>2.5.0</code>)</td><td>New features, changed generated output.</td><td>Moves on purpose, after reading the <a href="https://github.com/legionir/sweetmelon/blob/main/CHANGELOG.md" target="_blank" rel="noreferrer">changelog</a>.</td></tr><tr><td>Major (<code>3.0.0</code>)</td><td>May break the bridge or the config format.</td><td>Migrates on purpose.</td></tr></tbody></table><p>A fix for an older minor is made on its <code>release/x.y</code> branch and tagged there, so an app on <code>2.4</code> keeps getting <code>2.4.x</code> fixes without taking <code>2.5</code> features.</p><h2 id="what-is-checked" tabindex="-1">What is checked <a class="header-anchor" href="#what-is-checked" aria-label="Permalink to &quot;What is checked&quot;">​</a></h2><p><code>sweetmelon validate</code> and <code>sweetmelon doctor</code> compare <code>core:</code> with the CLI version (<code>sweetmelon --version</code>):</p><ul><li><code>core: &quot;2.4&quot;</code> accepts <code>2.4.0</code>, <code>2.4.1</code>, and so on.</li><li><code>core: &quot;2.4.1&quot;</code> needs patch 1 or newer.</li><li>Any other minor or major is an error.</li><li>A file without <code>core:</code> gets a warning.</li></ul><h2 id="pin-an-exact-tag" tabindex="-1">Pin an exact tag <a class="header-anchor" href="#pin-an-exact-tag" aria-label="Permalink to &quot;Pin an exact tag&quot;">​</a></h2><p>Use an exact tag (<code>v2.4.0</code>), never a branch or a floating tag:</p><div class="language-yaml vp-adaptive-theme line-numbers-mode"><button title="Copy Code" class="copy"></button><span class="lang">yaml</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">dependencies</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">  sweetmelon</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">    git</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">:</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      url</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">https://github.com/legionir/sweetmelon.git</span></span>
<span class="line"><span style="--shiki-light:#22863A;--shiki-dark:#85E89D;">      ref</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">: </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">v2.4.0</span></span></code></pre><div class="line-numbers-wrapper" aria-hidden="true"><span class="line-number">1</span><br><span class="line-number">2</span><br><span class="line-number">3</span><br><span class="line-number">4</span><br><span class="line-number">5</span><br></div></div><h2 id="how-a-release-is-made" tabindex="-1">How a release is made <a class="header-anchor" href="#how-a-release-is-made" aria-label="Permalink to &quot;How a release is made&quot;">​</a></h2><ol><li>Update <code>CHANGELOG.md</code> (a <code>## [x.y.z]</code> section) and <code>sweetmelon.yaml</code> <code>core:</code> when the minor changes.</li><li>Set <code>sweetmelonCoreVersion</code> in <code>lib/core_version.dart</code> and <code>version</code> in <code>pubspec.yaml</code>.</li><li>Tag <code>vx.y.z</code>. The release workflow stops if the tag and <code>lib/core_version.dart</code> differ, or if the changelog has no section for it.</li><li>For a new minor, create the branch <code>release/x.y</code> from the tag. Fixes for that minor are made there and tagged <code>vx.y.1</code>, <code>vx.y.2</code>, ...</li></ol><p>An app is never moved by a tag it did not ask for: tags are exact, there are no floating <code>v2</code> or <code>v2.4</code> tags.</p>`,14)])])}const m=a(n,[["render",o]]);export{g as __pageData,m as default};
